#!/bin/bash
# The Vacuum card's gate: types, unit tests, the integration's Python checks, the preview build, qa-vacuum; with a second argument the regressions of every other card too.
SP="${SP:?scratch folder}"; cd "$(dirname "$0")/.."
npx tsc --noEmit 2>&1 | head -6 | cut -c1-170; npm test 2>&1 | grep -E "^ℹ fail|^✖" | head -5; for t in test_config_guard; do python3 ../tests/components/atom_home/$t.py 2>&1 | tail -1; done; npm run -s preview:build 2>&1 | grep -E "error" | head -3
node scripts/qa-vacuum.mjs "$SP/agate$1" > "$SP/agate$1.log" 2>&1; head -1 "$SP/agate$1.log" | cut -c1-100; grep "^✘" "$SP/agate$1.log" | cut -c1-250 | awk '{k=$2; c[k]++; if(c[k]<=5)print}' | head -40; echo "by kind:"; grep "^✘" "$SP/agate$1.log" | awk '{print $2}' | sort | uniq -c | sort -rn | head -8
if [ -n "$2" ]; then echo "--- regressions"; npm run -s build 2>&1 | grep -E "error" | head -2; node scripts/qa-live-updates.mjs 2>&1 | tail -1 | cut -c1-80; node scripts/qa-feeder.mjs "$SP/rfeed" 2>&1 | head -6 | cut -c1-200; echo "[qa-air] $(node scripts/qa-air.mjs "$SP/reg-air" 2>&1 | head -1)"; echo "[qa-energy] $(node scripts/qa-energy.mjs "$SP/reg-energy" 2>&1 | head -1)"; echo "[qa-cameras] $(node scripts/qa-cameras.mjs "$SP/reg-cameras" 2>&1 | head -1)"; for q in qa-states qa-light qa-clock qa-camera qa-doorbell; do echo "[$q] $(node scripts/$q.mjs "$SP/reg-$q" 2>&1 | grep -E '[0-9]+/[0-9]+ checks|✘' | tail -3 | cut -c1-200 | tr '\n' ' ')"; done; for q in qa-setup qa-audit; do node scripts/$q.mjs "$SP/reg-$q" 2>&1 | python3 -c "import sys,re; t=sys.stdin.read(); print('[$q] false',len(re.findall(r'\"p\": false',t)),'true',len(re.findall(r'\"p\": true',t)), re.findall(r'\"n\": \"([^\"]+)\",\s*\"p\": false',t)[:5])"; done; fi
